// @ts-check
import tseslint from 'typescript-eslint';
import prettierConfig from 'eslint-config-prettier';
import eslintCommentsPlugin from '@eslint-community/eslint-plugin-eslint-comments';

// Primary keys are generated by Postgres (`uuidv7()`); an app-side random UUID
// would put a differently ordered key into the same index.
const NO_APP_SIDE_UUID_PATHS = [
  {
    name: 'node:crypto',
    importNames: ['randomUUID'],
    message: 'Primary keys come from Postgres uuidv7(); do not mint ids in the app.',
  },
  {
    name: 'crypto',
    importNames: ['randomUUID'],
    message: 'Primary keys come from Postgres uuidv7(); do not mint ids in the app.',
  },
];

// `z` is re-exported by packages/shared so every consumer parses with the one
// zod instance the generated schemas were built against.
const NO_DIRECT_ZOD_PATHS = [
  {
    name: 'zod',
    message: "Import `z` from '@sab/shared'; zod is owned by packages/shared.",
  },
];

// Rules that exist because the browser, not the server, runs this code.
const NO_STATIC_ANTD_FEEDBACK = {
  name: 'antd',
  importNames: ['message', 'notification'],
  message:
    "AntD's static message/notification render outside <ConfigProvider> (no theme, no translation). Use App.useApp().",
};

const NO_LOCAL_TIME_MESSAGE =
  'Dates are shown through lib/format-datetime.ts, which reads the clock in the business time zone, not the viewer.';

export default [
  {
    ignores: [
      '**/node_modules/**',
      '**/.next/**',
      '**/dist/**',
      '**/src/generated/**',
      '**/coverage/**',
      '**/*.d.{ts,mts,cts}',
      // The legacy bot lints itself with its own config until cutover.
      'root/**',
      'apps/*/scripts/**',
      'docs/**',
      'plans/**',
      'files/**',
      '.claude/**',
      '.serena/**',
      '.code-review-graph/**',
    ],
  },
  ...tseslint.configs.recommendedTypeChecked,
  {
    files: ['*.mjs', '*.cjs', '*.config.js', 'scripts/*.mjs'],
    ...tseslint.configs.disableTypeChecked,
  },
  {
    languageOptions: {
      parserOptions: {
        projectService: {
          allowDefaultProject: [
            '*.mjs',
            'scripts/*.mjs',
            'vitest.config.mts',
            'vitest.db.config.mts',
          ],
          maximumDefaultProjectFileMatchCount_THIS_WILL_SLOW_DOWN_LINTING: 20,
        },
        tsconfigRootDir: import.meta.dirname ?? process.cwd(),
      },
    },
    plugins: {
      '@eslint-community/eslint-comments': eslintCommentsPlugin,
    },
    rules: {
      '@typescript-eslint/no-deprecated': 'error',
      '@eslint-community/eslint-comments/no-unlimited-disable': 'error',
      '@eslint-community/eslint-comments/require-description': 'error',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
      ],
      '@typescript-eslint/no-explicit-any': 'warn',
      '@typescript-eslint/consistent-type-imports': ['error', { prefer: 'type-imports' }],
      'no-restricted-imports': [
        'error',
        {
          paths: [...NO_DIRECT_ZOD_PATHS, ...NO_APP_SIDE_UUID_PATHS],
          patterns: [
            {
              group: ['zod/*'],
              message: "Import `z` from '@sab/shared'; zod is owned by packages/shared.",
            },
          ],
        },
      ],
      'no-restricted-properties': [
        'error',
        {
          object: 'crypto',
          property: 'randomUUID',
          message: 'Primary keys come from Postgres uuidv7(); do not mint ids in the app.',
        },
      ],
    },
  },
  {
    // The web app: browser-only rules on top of the shared ones. A rule listed
    // here replaces the root entry for these files, so the shared paths repeat.
    files: ['apps/web/**/*.{ts,tsx,mts}'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [...NO_DIRECT_ZOD_PATHS, ...NO_APP_SIDE_UUID_PATHS, NO_STATIC_ANTD_FEEDBACK],
          patterns: [
            {
              group: ['zod/*'],
              message: "Import `z` from '@sab/shared'; zod is owned by packages/shared.",
            },
          ],
        },
      ],
      'no-restricted-properties': [
        'error',
        {
          object: 'crypto',
          property: 'randomUUID',
          message: 'Primary keys come from Postgres uuidv7(); do not mint ids in the app.',
        },
        { property: 'toLocaleString', message: NO_LOCAL_TIME_MESSAGE },
        { property: 'toLocaleDateString', message: NO_LOCAL_TIME_MESSAGE },
        { property: 'toLocaleTimeString', message: NO_LOCAL_TIME_MESSAGE },
        { property: 'getTimezoneOffset', message: NO_LOCAL_TIME_MESSAGE },
        { object: 'Modal', property: 'confirm', message: 'Use App.useApp().modal.confirm.' },
      ],
    },
  },
  {
    // The one place allowed to depend on zod directly.
    files: ['packages/shared/**'],
    rules: {
      'no-restricted-imports': ['error', { paths: NO_APP_SIDE_UUID_PATHS }],
    },
  },
  prettierConfig,
];
